import { z } from 'zod';

/** Shared UUID boundary contract. */
export const UuidSchema = z.string().uuid();
export type Uuid = z.infer<typeof UuidSchema>;

/** Public product routes use lowercase ASCII slugs generated by CatalogService (max 240). */
export const ProductSlugSchema = z.string().trim().min(1).max(240)
  .regex(/^[a-z0-9][a-z0-9-]*$/, 'Invalid product slug.');

/** Provider IDs are transport identifiers; the registry still enforces configured providers. */
export const PaymentProviderIdentifierSchema = z.string().min(1).max(64)
  .regex(/^[a-z][a-z0-9_-]*$/, 'Invalid payment provider identifier.');
